"audit_log\")\n}\n\n// Day 6: the budget guard that keeps the public sandbox from being exhausted.\nmodel ProviderUsage {\n  id        String   @id @default(uuid()) @db.Uuid\n  provider  String\n  day       DateTime @db.Date\n  calls     Int      @default(0)\n  updatedAt DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  @@unique([provider, day])\n  @@map(\"provider_usage\")\n}\n\n// Section 4.4: pins the compiler into every report, so a silent upgrade is visible.\nmodel ToolchainFingerprint {\n  id              String   @id @default(uuid()) @db.Uuid\n  provider        String\n  compilerVersion String   @map(\"compiler_version\")\n  stdcVersion     String   @map(\"stdc_version\")\n  pointerBits     Int      @map(\"pointer_bits\")\n  raw             String\n  hash            String\n  capturedAt      DateTime @default(now()) @map(\"captured_at\") @db.Timestamptz(6)\n\n  @@index([provider, capturedAt])\n  @@map(\"toolchain_fingerprints\")\n}\n"
